+    stripSourceInputOverrides(workspaceYamlPath);
+    stripSourceInputOverrides(lockfilePath);
+  '';
+in
+{
+  alignAggregateManifestSpecifiersScript = pkgs.writeShellScript "align-aggregate-manifest-specifiers" ''
